const STATIC=[{"id": "1.1", "s": 1, "t": "Реалізація державної політики у сфері захисту прав дитини, чіткого розмежування повноважень державних і місцевих органів влади у зазначеній сфері та посилення кадрового потенціалу відповідних органів", "term": "Протягом року", "u": "Упр. координації та методичного забезпечення", "co": [], "ok": true, "r": 10, "info": "Надано до Міністерства соціальної політики, сім’ї та єдності України пропозиції щодо вдосконалення нормативно-правових актів ВИКОНАНО Управлінням координації та методичного забезпечення з питань захисту прав дітей надано Управлінню правового забезпечення 8 службових із пропозиціями та зауваженнями до проєктів нормативно-правових актів. 1238/05.01-2/3466/2026 - Про погодження проекту постанови КМУ ", "g": "ВИКОНАНО", "un": false}, {"id": "1.2", "s": 1, "t": "Організація навчання з підвищення рівня професійної компетентності працівників служб у справах дітей", "term": "Протягом року", "u": "Упр. координації та методичного забезпечення", "co": [], "ok": true, "r": 11, "info": "Виконано. Проведено навчальні заходи з підвищення рівня професійної компетентності працівників служб у справах дітей: 3 навчальні заходи за темою «Пошук та відбір осіб, які виявили бажання прийняти дитину у свою сім’ю». Навчання проводилися МБО «Партнерство «Кожній дитині» за підтримки Представництва Дитячого фонду ООН (ЮНІСЕФ) в Україні. 2 навчальні заходи за темою «Служба у справах дітей як ключ", "g": "ВИКОНАНО", "un": false}, {"id": "1.3", "s": 1, "t": "Організація навчання для працівників органів виконавчої влади та органів місцевого самоврядування в сфері захисту прав дітей", "term": "Протягом року", "u": "Упр. координації та методичного забезпечення", "co": [], "ok": true, "r": 12, "info": "Виконано. Проведено навчальні заходи для працівників органів виконавчої влади та органів місцевого самоврядування у сфері захисту прав дітей: 1 онлайн-захід за темою «Як громади можуть впроваджувати послугу патронату над дитиною і чому це важливо» 1 онлайн-захід за темою «Особливості захисту прав та супроводу дитини під час надзвичайного та воєнного стану» 1 онлайн-захід за темою «Найкращі інтерес", "g": "ВИКОНАНО", "un": false}, {"id": "1.4", "s": 1, "t": "Координація та методичний супровід діяльності місцевих органів виконавчої влади, органів місцевого самоврядування, в межах повноважень, визначених законом", "term": "Протягом року", "u": "Упр. координації та методичного забезпечення", "co": [], "ok": true, "r": 13, "info": "Виконано. Проведено навчальні та координаційно-методичних заходів: 7 заходів за темою «Складні розмови під час евакуації дітей: кризова комунікація, деескалація, робота з опором батьків / осіб, які їх замінюють» для представників Харківської, Дніпропетровської, Миколаївської, Чернігівської, Сумської, Запорізької та Херсонської областей. 8 міжвідомчих нарад з представниками регіонів з питань виявле", "g": "ВИКОНАНО", "un": false}, {"id": "1.5", "s": 1, "t": "Здійснення моніторингу внесення службами у справах дітей інформації до банку даних Єдиної інформаційно- аналітичної системи ЄІАС «Діти»", "term": "Протягом року", "u": "Деп. розвитку сімейних форм і усиновлення", "co": ["Упр. координації та методичного забезпечення", "Деп. надання соціальної підтримки", "Деп. моніторингу та захисту прав дітей"], "ok": false, "r": 14, "info": "Виконується Департамент розвитку сімейних форм виховання та усиновлення проведено моніторинг та здійснено аналіз 232 обліково-статистичних карток дітей в інформаційно-аналітичній системі Діти» щодо внесення службами у справах дітей актуальної інформації про евакуацію/переміщення за межі України дітей-сиріт та дітей, позбавлених батьківського піклування, разом з законними представниками. Департамен", "g": "НЕ ВИКОНАНО", "un": false}, {"id": "2.1", "s": 2, "t": "Проведення заходів та організація навчань щодо порядку дій у випадках насильства та жорстокого поводження з дітьми відповідно до вимог Порядку реагування на випадки насильства та жорстокого поводження з дітьми, затвердженого постановою Кабінету Міністрів України від 19.11.2025 № 1513 (далі – Порядок № 1513)", "term": "Протягом року", "u": "Упр. координації та методичного забезпечення", "co": [], "ok": true, "r": 16, "info": "Виконано. Проведено навчальні заходи з питань реагування на випадки насильства та жорстокого поводження з дітьми: 6 регіональних навчальних заходів за темою «Міжвідомча взаємодія у разі виявлення та реагування на випадки насильства та жорстокого поводження з дітьми» для представників Запорізької, Дніпропетровської, Миколаївської, Чернігівської, Херсонської та Сумської областей. 2 навчальні заходи ", "g": "ВИКОНАНО", "un": false}, {"id": "2.2", "s": 2, "t": "Здійснення інформування про виявлення випадків насильства та жорстокого поводження з дітьми, відповідно до вимог Порядку № 1513", "term": "Протягом року", "u": "Відділ запобігання бездоглядності та насильству", "co": [], "ok": true, "r": 17, "info": "ВИКОНАНО Забезпечено інформування Національної соціальної сервісної служби про випадки насильства та жорстоке поводження з дітьми, відповідно до вимог Порядку № 1513 Забезпечено опрацювання інформації, отриманої від служб у справах дітей обласних та Київської міської державних (військових) адміністрацій, щодо виявлених випадків насильства та жорстокого поводження стосовно дітей, зокрема сексуально", "g": "ВИКОНАНО", "un": false}, {"id": "2.3", "s": 2, "t": "Забезпечення ведення обліку випадків насильства відповідно до вимог Порядку № 1513", "term": "Протягом року", "u": "Відділ запобігання бездоглядності та насильству", "co": [], "ok": true, "r": 18, "info": "ВИКОНАНО Забезпечено подання до Міністерства соціальної політики, сім’ї та єдності України (щокварталу та щороку) узагальненої інформації щодо випадків насильства відповідно до вимог Порядку № 1513 Забезпечено отримання, опрацювання та узагальнення інформації від служб у справах дітей обласних та Київської міської державних (військових) адміністрацій щодо випадків насильства та жорстокого поводжен", "g": "ВИКОНАНО", "un": false}, {"id": "2.4", "s": 2, "t": "Проведення інформаційно-роз’яснювальної роботи спрямованої на забезпечення міжвідомчої взаємодії з метою забезпечення соціального захисту дітей, які перебувають у складних життєвих обставинах, у тому числі дітей, які постраждали від жорстокого поводження", "term": "Протягом року", "u": "Відділ запобігання бездоглядності та насильству", "co": [], "ok": true, "r": 19, "info": "ВИКОНАНО Проведено інформаційно-роз’яснювальну роботу Забезпечено проведення інформаційно-роз’яснювальної та методичної роботи з працівниками служб у справах дітей обласних та Київської міської державних (військових) адміністрацій, органів місцевого самоврядування та інших суб’єктів системи захисту дітей щодо застосування законодавства з питань своєчасного виявлення дітей, які перебувають у складн", "g": "ВИКОНАНО", "un": false}, {"id": "2.5", "s": 2, "t": "Виконання Плану заходів на виконання Національного плану щодо впровадження Європейської гарантії для дітей в Україні на період до 2030 року, впровадженого постановою Кабінету Міністрів України «Про впровадження Європейської гарантії для дітей в Україні» від 19.11.2025 № 1558", "term": "Протягом року", "u": "Керівники підрозділів", "co": [], "ok": true, "r": 20, "info": "Виконано План заходів. 1) У межах компетенції Служби здійснювалася робота з питань своєчасного виявлення дітей, які перебувають у складних життєвих обставинах, запобігання дитячій бездоглядності, насильству та жорстокому поводженню стосовно дітей, забезпечення міжвідомчої взаємодії та організації соціального захисту дітей, які потребують додаткової підтримки. Забезпечено координацію діяльності рег", "g": "ВИКОНАНО", "un": false}, {"id": "3.1", "s": 3, "t": "Забезпечує ведення обліку дітей, які опинилися у складних життєвих обставинах, а також дітей, влаштованих до сімей патронатних вихователів, закладів, які здійснюють інституційний догляд і виховання дітей", "term": "Протягом року", "u": "Деп. надання соціальної підтримки", "co": ["Деп. моніторингу та захисту прав дітей", "Деп. розвитку сімейних форм і усиновлення"], "ok": true, "r": 22, "info": "Виконано Департаментом надання соціальної підтримки у сфері захисту прав дітей проведено моніторинг дотримання прав дітей, які опинилися у складних життєвих обставинах, зокрема ведення службами у справах дітей обліку дітей, які опинилися у складних життєвих обставинах, повноти внесених до Єдиної інформаційно-аналітичної системи «Діти» даних щодо дітей. За даними Єдиної інформаційно-аналітичної сис", "g": "ВИКОНАНО", "un": false}, {"id": "3.2", "s": 3, "t": "Організаційно-методичне забезпечення соціальної підтримки та соціальних послуг сім’ям з дітьми, які перебувають у складних життєвих обставинах, багатодітним сім’ям, сім’ям опікунів, піклувальників, прийомним сім’ям, дитячим будинкам сімейного типу, усиновлювачам, сім’ям патронатних вихователів", "term": "Протягом року", "u": "Деп. надання соціальної підтримки", "co": ["Деп. розвитку сімейних форм і усиновлення"], "ok": true, "r": 23, "info": "Виконано Забезпечено інформаційно- роз’яснювальну роботу та координацію діяльності структурних підрозділів місцевих органів виконавчої влади, органів місцевого самоврядування, що здійснюють соціальну роботу, з питань організації надання соціальної підтримки та соціальних послуг сім'ям з дітьми, які потребують особливої уваги. Під час оперативних нарад з представниками регіональних та місцевих служ", "g": "ВИКОНАНО", "un": false}, {"id": "3.3", "s": 3, "t": "Забезпечення збору та узагальнення інформації про кількість дітей, яким надано статус дитини, яка постраждала внаслідок воєнних дій та збройних конфліктів", "term": "Протягом року", "u": "Деп. моніторингу та захисту прав дітей", "co": [], "ok": true, "r": 24, "info": "Виконано. Забезпечено проведення моніторингу щодо кількості дітей, яким встановлено статус дитини, яка постраждала внаслідок воєнних дій та збройних конфліктів. Станом на 01.10.2026 відповідно до Порядку надання статусу дитини, яка постраждала внаслідок воєнних дій та збройних конфліктів, затвердженого постановою Кабінету Міністрів України від 05.04.2017 № 268 496 092 дітям встановлено зазначений ", "g": "ВИКОНАНО", "un": false}, {"id": "4.1", "s": 4, "t": "Здійснення заходів з пошуку та повернення на підконтрольну Україні територію дітей, які депортовані або примусово переміщенні, або перебували під ризиком депортації та/або примусового переміщення внаслідок збройної агресії Російської Федерації проти України, або осіб з числа дітей", "term": "Протягом року", "u": "Деп. моніторингу та захисту прав дітей", "co": [], "ok": true, "r": 26, "info": "Виконано. Забезпечено виконання повноважень щодо інформування відповідно до Порядку виявлення, повернення, забезпечення супроводу та реінтеграції дітей, які депортовані або примусово переміщені, або перебували під ризиком депортації та/або примусового переміщення внаслідок збройної агресії Російської Федерації проти України, або осіб з числа дітей», затвердженого постановою Кабінету Міністрів Укра", "g": "ВИКОНАНО", "un": false}, {"id": "4.2", "s": 4, "t": "Виплата підйомної допомоги законному представнику дитини або уповноваженій ним особі, або особі з числа дітей відповідно до Порядку № 551", "term": "Протягом року", "u": "Деп. моніторингу та захисту прав дітей", "co": [], "ok": true, "r": 27, "info": "Виконано. Проведено інформаційну роботу щодо отримання підйомної допомоги: розроблено відеоролик щодо отримання підйомної допомоги https://www.facebook.com/share/r/1FNKjPsRyq/?mibextid=wwXIfr розроблено спільно з Карітас Україна, Міністерство соціальної політики, сім'ї та єдності України інформаційну брошуру щодо виплати підйомної допомоги За період з 01.01.2026 по 30.09.2026 службою опрацьовано 7", "g": "ВИКОНАНО", "un": false}, {"id": "4.3", "s": 4, "t": "Забезпечення участі в засіданні міжвідомчої команди супроводу з метою затвердження, перегляду, моніторингу виконання плану заходів із забезпечення супроводу та реінтеграції дитини, а також координації реалізації пакетів допомоги", "term": "Протягом року", "u": "Деп. моніторингу та захисту прав дітей", "co": [], "ok": true, "r": 28, "info": "Виконано. Організовано роботу з органами виконавчої влади, органами місцевого самоврядування та громадськими об’єднаннями, міжнародними організаціями щодо забезпечення потреб дітей та їх сімей, які повернулися з місць депортації, після примусового переміщення шляхом проведення робочих нарад. Працівниками Служби взято участь у 32 засіданнях міжвідомчої команди супроводу та реінтеграції дітей, на як", "g": "ВИКОНАНО", "un": false}, {"id": "5.1", "s": 5, "t": "Забезпечення безпосередньої взаємодії із закордонними дипломатичними установами України та закордонними дипломатичними представництвами в Україні з питань забезпечення прав та найкращих інтересів дітей громадян України за кордоном", "term": "Протягом року", "u": "Деп. моніторингу та захисту прав дітей", "co": [], "ok": true, "r": 30, "info": "Виконано. Забезпечено безпосередню взаємодію із закордонними дипломатичними установами України з питань захисту прав та найкращих інтересів дітей – громадян України, які перебувають за межами України. Надано роз’яснення щодо встановлення опіки та піклування над дітьми й функціонування сімейних форм виховання відповідно до законодавства України (лист від 15.10.2026 № 4990/2026) для доведення відпов", "g": "ВИКОНАНО", "un": false}, {"id": "5.2", "s": 5, "t": "Участь у моніторингах умов перебування дітей за межами України, проведенні оцінювання стану задоволення потреб дітей, які проживають або зараховані до закладів різних типів, форм власності та підпорядкування на цілодобове перебування", "term": "Протягом року", "u": "Деп. моніторингу та захисту прав дітей", "co": [], "ok": true, "r": 31, "info": "Виконано. Здійснено терміновий моніторинг стану утримання дітей, які тимчасово переміщенні (евакуйовані) до Італійської Республіки шляхом заповнення анкетдистанційний моніторинг умов перебування дітей за межами України відповідно до наказу Міністерства соціальної політики сім'ї та єдності України від 20.05.2026 № 157 Моніторингових візитів за межі України не здійснювалось. Згідно з пунктом 36-1 По", "g": "ВИКОНАНО", "un": false}, {"id": "5.3", "s": 5, "t": "Утворення та координація роботи міжвідомчої команди реінтеграції для планування та координації заходів, спрямованих на реінтеграцію дітей в суспільне життя, а також їх підготовку до повернення на виховання до батьків, інших законних представників або до влаштування в сім’ї громадян України (під опіку, піклування, у прийомну сім’ю, дитячий будинок сімейного типу, усиновлення), або до самостійного життя для кожної з груп повернутих тимчасово переміщених (евакуйованих) дітей із за кордону", "term": "Протягом року", "u": "Деп. моніторингу та захисту прав дітей", "co": [], "ok": true, "r": 32, "info": "Виконано. Опрацьовано 8 повідомлень від Нацсоцслужби за інформацією щодо повернення 26 дітей, з яких: 24 дитини-сироти та дитини, позбавлених батьківського піклування; 2 дитини, які перебувають у складних життєвих обставинах. Вищезазначені діти були повернуті з: Федеративної Республіки Німеччина – 1 дитина; Республіки Польща – 23 дитини; Королівства Нідерландів – 2 дитини. Під час моніторингових в", "g": "ВИКОНАНО", "un": false}, {"id": "5.4", "s": 5, "t": "Заходи щодо повернення тимчасово переміщених (евакуйованих) дітей, які отримують інституційний догляд та виховання, з місць тимчасового переміщення (евакуації) відповідно до їх потреб та найкращих інтересів", "term": "Протягом року", "u": "Деп. моніторингу та захисту прав дітей", "co": [], "ok": true, "r": 33, "info": "Виконано. Забезпечено координацію та міжвідомчу взаємодію з питань повернення в Україну тимчасово переміщених (евакуйованих) дітей, які отримують інституційний догляд та виховання за кордоном. Проведено 6 онлайн-нарад щодо опрацювання питання повернення дітей із Центру соціально-психологічної реабілітації дітей № 1 Криворізької міської ради та Центру соціально-психологічної реабілітації дітей Крив", "g": "ВИКОНАНО", "un": false}, {"id": "6.1", "s": 6, "t": "Захист житлових і майнових прав дітей-сиріт, дітей, позбавлених батьківського піклування, та осіб з їх числа", "term": "Протягом року", "u": "Деп. розвитку сімейних форм і усиновлення", "co": [], "ok": false, "r": 35, "info": "Виконується Оновлено склад робочої групи з розробки порядку захисту житлових і майнових прав дітей-сиріт та дітей, позбавлених батьківського піклування, та осіб з їх числа (далі – Порядок). Розроблено проєкт Порядку. Відбувається процес внутрішнього узгодження проєкту членами робочої групи.", "g": "НЕ ВИКОНАНО", "un": false}, {"id": "7.1", "s": 7, "t": "Забезпечення проведення інформаційно-роз’яснювальної роботи щодо соціальної підтримки, у тому числі надання соціальних послуг сім’ям з дітьми", "term": "Протягом року", "u": "Деп. надання соціальної підтримки", "co": [], "ok": true, "r": 38, "info": "Виконано Підвищено рівень поінформованості населення щодо соціальної підтримки сімей з дітьми, зокрема підготовлено та розміщено на офіційному вебсайті Служби відповідні інформаційні матеріали стосовно програм соціальної підтримки дітей та сімей: в рубриці “Соціальна підтримка сімей з дітьми” - про запровадження в територіальних громадах соціальних послуг для сімей, які виховують дітей з особливим", "g": "ВИКОНАНО", "un": false}, {"id": "7.2", "s": 7, "t": "Забезпечення проведення інформаційно-роз’яснювальної роботи щодо надання послуги раннього втручання", "term": "Протягом року", "u": "Деп. надання соціальної підтримки", "co": [], "ok": true, "r": 39, "info": "Виконано Підвищено рівень поінформованості населення щодо послуги раннього втручання, зокрема підготовлено та розміщено на офіційному вебсайті Служби відповідні інформаційні матеріали стосовно впровадження послуги раннього втручання, у тому числі в розрізі регіонів, у розділі «Програми підтримки дітей і сімей», в рубриці «Раннє втручання» за посиланням: https://children.gov.ua/rannye-vtruchannya Н", "g": "ВИКОНАНО", "un": false}, {"id": "7.3", "s": 7, "t": "Аналіз реалізації політики з впровадження соціальної роботи та надання соціальних послуг сім'ям з дітьми", "term": "Протягом року", "u": "Деп. надання соціальної підтримки", "co": [], "ok": false, "r": 40, "info": "Виконується З метою аналізу стану реалізації політики щодо впровадження соціальної роботи та надання соціальних послуг сім’ям з дітьми, забезпечено моніторинг соціальної роботи в територіальних громадах щодо профілактики соціального сирітства, попередження відмов від новонароджених дітей. З метою підготовки відповідної інформаційно-аналітичної записки направлено запит до Національної соціальної се", "g": "НЕ ВИКОНАНО", "un": false}, {"id": "7.4", "s": 7, "t": "Забезпечення координації здійснення заходів щодо розвитку в територіальних громадах сімей патронатних вихователів", "term": "Протягом року", "u": "Деп. розвитку сімейних форм і усиновлення", "co": [], "ok": false, "r": 41, "info": "Виконується Налагоджено координацію заходів із розвитку мережі сімей патронатних вихователів у територіальних громадах та збільшено кількість таких сімей. Станом на 30.06.2026, за оперативною інформацією служб у справах дітей обласних, Київської міської державних (військових) адміністрацій, в Україні функціонує 706 сімей патронатних вихователів, в яких перебуває 1 408 дітей, у тому числі 12 дітей ", "g": "НЕ ВИКОНАНО", "un": false}, {"id": "7.5", "s": 7, "t": "Забезпечення реалізації експериментального проєкту із забезпечення догляду і виховання дітей-сиріт та дітей, позбавлених батьківського піклування, в умовах наближених до сімейних, впровадженого постановою Кабінету Міністрів України від 01.10.2025 № 1285 «Деякі питання реалізації експериментального проекту із забезпечення догляду і виховання дітей-сиріт та дітей, позбавлених батьківського піклування, в умовах, наближених до сімейних, на засадах співфінансування з державного бюджету та місцевих бюджетів»", "term": "Протягом року", "u": "Упр. стратегічного розвитку та аналізу процесів", "co": ["Упр. координації та методичного забезпечення", "Деп. розвитку сімейних форм і усиновлення"], "ok": true, "r": 42, "info": "Виконано. Проведено інформаційно-роз’яснювальну роботу щодо реалізації послуги «Сімейна домівка». Спільно з Координаційним центром з розвитку сімейного виховання та догляду дітей і Представництвом Дитячого фонду ООН (ЮНІСЕФ) в Україні організовано та проведено спеціальну підготовку потенційних працівників надавачів послуги «Сімейна домівка». Організовано проведення навчань у якому взяли участь 28 ", "g": "ВИКОНАНО", "un": false}, {"id": "8.1", "s": 8, "t": "Забезпечення реалізації виконання програми «пакунок малюка», затвердженої постановою Кабінету Міністрів України від 25.11.2020 № 1180 «Деякі питання надання одноразової натуральної допомоги «пакунок малюка»» (далі – постанова № 1180)", "term": "Протягом року", "u": "Деп. надання соціальної підтримки", "co": [], "ok": false, "r": 44, "info": "Виконується Сформовано планові показники обсягу потреби в одноразовій натуральній допомозі «пакунок малюка» для планування бюджетних коштів на 2027 рік в кількості 188716 тис. шт. та подано до Мінсоцполітики листом № 94/04.03-2/ від 09.01.2026; сформовано уточнюючу потребу в кількості 146437 тис. шт. (подано до Мінсоцполітики листом № 2871/04.03-2/ від 24.06.2026). Забезпечено координацію поставок", "g": "НЕ ВИКОНАНО", "un": false}, {"id": "8.2", "s": 8, "t": "Забезпечення проведення інформаційно-роз’яснювальної роботи щодо соціальних програм підтримки сімей з дітьми", "term": "Протягом року", "u": "Деп. надання соціальної підтримки", "co": [], "ok": true, "r": 45, "info": "Виконано Проведено інформаційно- роз'яснювальну роботу щодо соціальних програм підтримки сімей з дітьми, зокрема, з метою інформування населення на офіційному вебсайті Служби розміщено інформаційні матеріали стосовно програм підтримки дітей та сімей:в розділі “соціальна підтримка сімей з дітьми”: у рубриці “Пакунок малюка” - про отримання одноразової натуральної допомоги “пакунок малюка” та грошов", "g": "ВИКОНАНО", "un": false}, {"id": "8.3", "s": 8, "t": "Забезпечення реалізації послуги з догляду за дитиною до трьох років «муніципальна няня»", "term": "Протягом року", "u": "Деп. надання соціальної підтримки", "co": [], "ok": true, "r": 46, "info": "Виконано Забезпечено збір та узагальнення інформації про призначення та виплату відшкодування вартості послуги з догляду за дитиною до трьох років «муніципальна няня»: сформовано планові показники обсягу потреби відшкодування вартості послуги ,,муніципальна няня” для планування бюджетних коштів на 2027 рік в кількості 22592 особи; забезпечено збір та узагальнення щомісячної інформації про призначе", "g": "ВИКОНАНО", "un": false}, {"id": "8.4", "s": 8, "t": "Забезпечення координації здійснення заходів щодо соціальної підтримки багатодітних сімей уповноваженими органами з питань захисту прав дітей", "term": "Протягом року", "u": "Деп. надання соціальної підтримки", "co": [], "ok": true, "r": 47, "info": "Виконано Забезпечено роботу щодо опрацювання подання на присвоєння почесного звання «Мати-героїня», зокрема опрацьовано 718 пакетів документів на присвоєння почесного звання України «Мати-героїня» (100% від отриманих на звітну дату), підготовлено проєкти рішень про підтримку 703 клопотань обласних, Київської міської, державних (військових) адміністрацій.", "g": "ВИКОНАНО", "un": false}, {"id": "9.1", "s": 9, "t": "Забезпечення організації оздоровлення та відпочинку дітей шляхом проведення інформаційно-роз’яснювальної роботи та координації діяльності структурних підрозділів обласних, Київської міської державних (військових) адміністрацій, до компетенції яких належать питання організації оздоровлення та відпочинку дітей, дитячих закладів оздоровлення та відпочинку всіх типів та форм власності, а також об’єднань, підприємств, установ та організацій, незалежно від форми власності, які забезпечують оздоровлення та відпочинок дітей", "term": "Протягом року", "u": "Деп. надання соціальної підтримки", "co": [], "ok": true, "r": 49, "info": "Виконано Виконано організаційні, процедурні та технічні заходи щодо організації оздоровлення дітей, забезпечено координацію діяльності та інформаційну підтримку відповідальних регіональних структурних підрозділів, місцевих органів виконавчої влади, дитячих оздоровчих закладів та співпрацю і взаємодію з іншими заінтересованими центральними органами виконавчої влади та державними установами. Налагод", "g": "ВИКОНАНО", "un": false}, {"id": "9.2", "s": 9, "t": "Забезпечення формування кількісної потреби у путівках до ДПУ «МДЦ «Артек» в регіонах шляхом координації діяльності відповідальних структурних підрозділів обласних, Київської міської державних (військових) адміністрацій. Формування розподілу путівок до ДПУ «МДЦ «Артек» у розрізі адміністративно-територіальних одиниць за результатами опрацювання потреби, поданої регіонами, та в межах фактичної кількості", "term": "Протягом року", "u": "Деп. надання соціальної підтримки", "co": [], "ok": true, "r": 50, "info": "Виконано Сформовано розподіл путівок до ДПУ «МДЦ «Артек» відповідно до потреб регіонів на дванаддцять оздоровчих тематичних змін, згідно з затвердженим на 2026 рік планом-графіком. Першочергово забезпечено потребу в путівках для дітей з 10 регіонів, а саме: Дніпропетровська, Донецька, Запорізька, Луганська, Миколаївська, Одеська, Сумська, Харківська, Херсонська, Чернігівська області. Підготовлено ", "g": "ВИКОНАНО", "un": false}, {"id": "9.3", "s": 9, "t": "Здійснення координації діяльності суб’єктів, що проводять роботу з виїзду груп дітей за кордон на оздоровлення та відпочинок; опрацювання документів для надання згоди на виїзд груп дітей за кордон", "term": "Протягом року", "u": "Деп. надання соціальної підтримки", "co": [], "ok": true, "r": 51, "info": "Виконано Опрацьовано п’ять пакетів документів та надано 4 згоди Служби на виїзд дітей за кордон на відпочинок та оздоровлення: Благодійної організації «Гуру Фонд» та надано Згоди на виїзд: - до Чорногорії організованої групи чисельністю 35 дітей з 22.03.2026 по 30.03.2026 (Згода від 19.03.2026 № 1156/04.02-9/3620/2026); - до Італійської Республіки організованої групи чисельністю 41 дитина з 29.06.", "g": "ВИКОНАНО", "un": false}, {"id": "10.1", "s": 10, "t": "Здійснення заходів щодо організації проведення державної атестації дитячих закладів оздоровлення та відпочинку, надання їм відповідної методичної допомоги, погодження регіональних планів атестації, які затверджуються на 5 років; підведення підсумків атестації дитячих закладів оздоровлення та відпочинку, забезпечення оприлюднення інформації", "term": "Протягом року", "u": "Деп. надання соціальної підтримки", "co": [], "ok": true, "r": 53, "info": "Виконано Організовано проведення державної атестації дитячих закладів оздоровлення та відпочинку. Забезпечено погодження регіональних планів проведення державної атестації дитячих закладів оздоровлення та відпочинку, затверджених обласними уповноваженими органами. У 2026 році здійснено опрацювання та погодження регіональних планів 5 областей щодо проведення державної атестації дитячих закладів озд", "g": "ВИКОНАНО", "un": false}, {"id": "10.2", "s": 10, "t": "Здійснення аналізу стану збереження і розвитку мережі дитячих закладів оздоровлення та відпочинку та інформації про послуги, які вони надають", "term": "Протягом року", "u": "Деп. надання соціальної підтримки", "co": [], "ok": true, "r": 54, "info": "Виконано Проведено відповідну роботу з обласними, Київською міською державними (військовими) адміністраціями щодо аналізу стану збереження та розвитку мережі дитячих закладів оздоровлення та відпочинку, забезпечення їх функціонування, зокрема здійснено збір, аналіз та узагальнення інформації регіонів щодо: - переліку дитячих закладів оздоровлення та відпочинку, які планують проведення оздоровчої к", "g": "ВИКОНАНО", "un": false}, {"id": "10.3", "s": 10, "t": "Забезпечення надання інформаційної підтримки регіонам у формуванні Державного реєстру майнових об’єктів оздоровлення та відпочинку дітей, виконання функцій головного реєстратора Державного реєстру майнових об’єктів оздоровлення та відпочинку дітей", "term": "Протягом року до", "u": "Деп. надання соціальної підтримки", "co": [], "ok": false, "r": 55, "info": "Виконується Забезпечено інформаційну підтримку регіонів та здійснено функції головного реєстратора Державного реєстру майнових об’єктів оздоровлення та відпочинку дітей, що сприяло актуалізації даних. Державний реєстр майнових об’єктів оздоровлення та відпочинку дітей (далі – Реєстр) містить дані про 380 дитячих закладів оздоровлення та відпочинку. Службою забезпечено методичну, інформаційну допом", "g": "НЕ ВИКОНАНО", "un": false}, {"id": "11.1", "s": 11, "t": "Проведення інформаційно-роз’яснювальної роботи щодо популяризації розвитку сімейних форм виховання та усиновлення", "term": "Протягом року", "u": "Деп. розвитку сімейних форм і усиновлення", "co": [], "ok": false, "r": 58, "info": "Виконується Надано 42 консультації телефоном кандидатам в усиновлювачі щодо порядку усиновлення. Розглянуто 16 звернень громадян України та 18 звернень іноземних громадян про надання роз’яснення щодо порядку усиновлення, переліку документів, постановки на облік кандидатів в усиновлювачі, надання інформації щодо дітей, які можуть бути усиновлені, розгляду справ в суді", "g": "НЕ ВИКОНАНО", "un": false}, {"id": "11.2", "s": 11, "t": "Здійснення моніторингу та координації діяльності служб у справах дітей щодо постановки дітей–сиріт, та дітей, позбавлених батьківського піклування, які можуть бути усиновленні, на місцевий та регіональний обліки з усиновлення", "term": "Протягом року", "u": "Деп. розвитку сімейних форм і усиновлення", "co": [], "ok": false, "r": 59, "info": "Виконується За 9 місяців 2026 року: в базі ЄІАС “Діти” здійснено моніторинг роботи служб у справах дітей щодо постановки дітей–сиріт, та дітей, позбавлених батьківського піклування, які можуть бути усиновленні, на місцевий та регіональний обліки з усиновлення відносно 1528 дітей, службам у справах дітей надано 933 методичні консультації щодо правових підстав постановки дітей на місцевий, регіональ", "g": "НЕ ВИКОНАНО", "un": false}, {"id": "11.3", "s": 11, "t": "Ведення централізованого обліку дітей-сиріт і дітей, позбавлених батьківського піклування, які можуть бути усиновлені, а також обліку іноземців та громадян України, які проживають за межами України і бажають усиновити дітей", "term": "Протягом року", "u": "Деп. розвитку сімейних форм і усиновлення", "co": [], "ok": false, "r": 60, "info": "Виконується Станом на 30.09.2026: 1528 дітей поставлено на централізований облік з усиновлення, 275 дітей знято з обліку. Окрім того, опрацьовано направлені службами у справах дітей оновлені дані стосовно 1241 анкети дітей, які перебувають на централізованому обліку з усиновлення (висновок про стан здоров’я, фізичний та розумовий розвиток дитини, відомості про місце її проживання (перебування), фо", "g": "НЕ ВИКОНАНО", "un": false}, {"id": "11.4", "s": 11, "t": "Апробування пілотного проєкту «День відкритих сердець» з підтримки дітей-сиріт та дітей, позбавлених батьківського піклування", "term": "Протягом року", "u": "Упр. координації та методичного забезпечення", "co": ["Деп. розвитку сімейних форм і усиновлення"], "ok": false, "r": 61, "info": "Виконується. Захід заплановано на листопад 2026 року. У межах апробування пілотного проєкту «День відкритих сердець» з підтримки дітей-сиріт та дітей, позбавлених батьківського піклування, заплановано проведення відповідного заходу у місті Чернівці..(Управління координації та методичного забезпечення з питань захисту прав дітей)", "g": "НЕ ВИКОНАНО", "un": false}, {"id": "12.1", "s": 12, "t": "Сприяння розвитку сімейних форм виховання, влаштуванню дітей-сиріт та дітей, позбавлених батьківського піклування, у дитячі будинки сімейного типу, прийомні сім’ї, передачі таких дітей під опіку, піклування", "term": "Протягом року", "u": "Деп. розвитку сімейних форм і усиновлення", "co": [], "ok": false, "r": 63, "info": "Виконується Відповідно до Порядку та умов надання у 2026 році субвенції з державного бюджету місцевим бюджетам на реалізацію програми публічних інвестицій із забезпечення житлом дитячих будинків сімейного типу, затвердженого постановою Кабінету Міністрів України від 04 червня 2026 року № 717, у 2026 році заплановано придбання житла для 17 новоутворених дитячих будинків сімейного типу.", "g": "НЕ ВИКОНАНО", "un": false}, {"id": "12.2", "s": 12, "t": "Здійснення моніторингу сімейних форм виховання", "term": "Протягом року", "u": "Деп. розвитку сімейних форм і усиновлення", "co": [], "ok": false, "r": 64, "info": "Виконується Департамент забезпечує комплексний процес збору, аналізу, перевірки та оцінки інформації про те, як реалізуються права дітей-сиріт та дітей, позбавлених батьківського піклування, які влаштовані в сімейні умови (опіка, піклування, прийомні сім’ї, дитячі будинки сімейного типу — ДБСТ, патронатні сім'ї). Проводиться моніторинг повноти та актуальності внесення місцевими службами у справах ", "g": "НЕ ВИКОНАНО", "un": false}, {"id": "12.3", "s": 12, "t": "Здійснення моніторингу влаштування тимчасово переміщених (евакуйованих) дітей, які залишилися без батьківського піклування, дітей-сиріт та дітей, позбавлених батьківського піклування, до сімейних форм виховання", "term": "Протягом року", "u": "Деп. розвитку сімейних форм і усиновлення", "co": [], "ok": false, "r": 65, "info": "Виконується Здійснюється моніторинг влаштування тимчасово переміщених (евакуйованих) дітей, які залишилися без батьківського піклування, дітей-сиріт та дітей, позбавлених батьківського піклування, у сімейні форми виховання Відділом розвитку сімейних форм виховання щомісяця опрацьовується та узагальнюється інформацію обласних державних (військових) адміністрацій та виконавчого органу Київської місь", "g": "НЕ ВИКОНАНО", "un": false}, {"id": "13.1", "s": 13, "t": "Забезпечення опрацювання та узагальнення звітності № 1-ОПС (річна) «Звіт про кількість дітей-сиріт і дітей, позбавлених батьківського піклування»", "term": "До 10 березня", "u": "Деп. розвитку сімейних форм і усиновлення", "co": [], "ok": true, "r": 68, "info": "Виконано На виконання наказу Міністерства соціальної політики України від 15 червня 2017 року № 994 «Про затвердження форми звітності № 1-ОПС (річна) «Звіт про кількість дітей-сиріт і дітей, позбавлених батьківського піклування» та інструкції щодо її заповнення» (зареєстрованого у Міністерстві юстиції України від 13 липня 2017 року № 856/30724) (зі змінами), опрацьовано статистичні дані отримані в", "g": "ВИКОНАНО", "un": false}, {"id": "13.2", "s": 13, "t": "Забезпечення опрацювання та узагальнення інформації статистичної звітності № 1-ДБСТ (річна) «Звіт про функціонування дитячих будинків сімейного типу та прийомних сімей»", "term": "До 28 січня", "u": "Деп. розвитку сімейних форм і усиновлення", "co": [], "ok": true, "r": 69, "info": "Виконано На виконання наказу Мінсоцполітики від 26.01.2012 № 36 «Про затвердження форми звітності № 1-ДБСТ (річна) «Звіт про функціонування дитячих будинків сімейного типу та прийомних сімей» та інструкція щодо її заповнення» опрацьовано статистичні дані отримані від обласних та Київської міської державних (військових) адміністрацій, звіт № 1-ДБСТ за 2025 рік (лист від 28.01.2026 № 387/02.01-14/) ", "g": "ВИКОНАНО", "un": false}, {"id": "13.3", "s": 13, "t": "Забезпечення опрацювання та узагальнення інформації до звіту № 1-ЗЖД (річна) «Звіт про збереження житлових прав дітей-сиріт та дітей, позбавлених батьківського піклування» та інструкції щодо її заповнення»", "term": "До 01 березня", "u": "Деп. розвитку сімейних форм і усиновлення", "co": [], "ok": true, "r": 70, "info": "Виконано На виконання наказу Мінсоцполітики від 26.01.2012 № 36 «Про затвердження форми звітності № 1-ЗЖД (річна) «Звіт про збереження житлових прав дітей-сиріт і дітей, позбавлених батьківського піклування» та інструкція щодо її заповнення» узагальнено річний звіт № 1-ЗЖД за 2025 рік (лист від 02.03.2026 № 877/05.01-2/2650/2026), який направлено на Міністерство соціальної політики, сім'ї та єднос", "g": "ВИКОНАНО", "un": false}, {"id": "13.4", "s": 13, "t": "Забезпечення збору та узагальнення інформації про виконання пунктів операційного плану заходів на 2024–2026 роки з реалізації Стратегії забезпечення права кожної дитини в Україні на зростання в сімейному оточенні на 2024–2028 роки, затвердженого розпорядженням Кабінету Міністрів України від 26.11.2024 № 1201-р", "term": "До 01 травня", "u": "Упр. координації та методичного забезпечення", "co": [], "ok": true, "r": 71, "info": "Виконано. Узагальнено та подано до Кабінету Міністрів України інформацію про стан виконання плану заходів Узагальнено та подано до Кабінету Міністрів України інформацію про стан виконання плану заходів на національному та регіональному рівнях за 2025 рік на виконання пункту 5 розпорядження Кабінету Міністрів України від 26.11.2024 № 1201-р. Інформацію направлено листом Державної служби України у с", "g": "ВИКОНАНО", "un": false}, {"id": "13.5", "s": 13, "t": "Забезпечення опрацювання інформації щодо реалізації державних субвенцій (код 2511800, 2511180)", "term": "Протягом року", "u": "Деп. розвитку сімейних форм і усиновлення", "co": [], "ok": false, "r": 72, "info": "Виконується На виконання пункту 22 Порядку та умов надання у 2026 році субвенції з державного бюджету місцевим бюджетам на реалізацію програми публічних інвестицій із забезпечення житлом дитячих будинків сімейного типу, затвердженого постановою Кабінету Міністрів України від 04.06.2026 № 717 (код 2511800), підготовлено звітні матеріали та подано до Мінсоцполітики (листи від 09.07.2026 № 3095/05.01", "g": "НЕ ВИКОНАНО", "un": false}, {"id": "13.6", "s": 13, "t": "Опрацювання інформації про випадки суїцидів, нещасних випадків, жорстокого поводження з дітьми, залишення дітей без нагляду чи у небезпеці, які призвели до їх смерті, загибелі або тяжких тілесних ушкоджень", "term": "Протягом року", "u": "Відділ запобігання бездоглядності та насильству", "co": [], "ok": true, "r": 73, "info": "ВИКОНАНО Підготовлено звітні матеріали та подано Міністерства соціальної політики, сім’ї та єдності України Забезпечено систематичне отримання, опрацювання та узагальнення інформації від служб у справах дітей обласних та Київської міської державних (військових) адміністрацій щодо випадків загибелі, смерті, тяжкого травмування дітей, суїцидів і суїцидальних спроб, нещасних випадків, насильства, жор", "g": "ВИКОНАНО", "un": false}, {"id": "13.7", "s": 13, "t": "Забезпечення опрацювання та узагальнення звітності щодо оздоровлення та відпочинку дітей", "term": "Протягом року", "u": "Деп. надання соціальної підтримки", "co": [], "ok": true, "r": 74, "info": "Виконано Опрацьовано та узагальнено звітну інформацію від обласних та Київської міської державних (військових) адміністрацій: - оперативної інформації від регіонів щодо фактичних показників оздоровлення та відпочинку дітей у 2025 році та надіслано Мінсоцполітики листом від 08.01.2026 № 83/04.02-13/9626/2025. - звітів регіонів за формами № 2-ОБК «Звіт про охоплення дітей шкільного віку оздоровлення", "g": "ВИКОНАНО", "un": false}, {"id": "13.8", "s": 13, "t": "Забезпечення опрацювання та узагальнення інформації до звітів: № 1-Центр «Звіт про діяльність центру(ів) соціально-психологічної реабілітації дітей»; № 2-притулок «Зведений звіт про рух контингенту дітей притулків для дітей»", "term": "До 25 липня", "u": "Деп. моніторингу та захисту прав дітей", "co": [], "ok": true, "r": 75, "info": "Виконано. Узагальнено та подано до Міністерства соціальної політики, сім’ї та єдності України, відповідно до Наказу Міністерства України у справах сім’ї, молоді та спорту від 25.12.2006 № 4335 «Про затвердження форми звітності № 1-Центр «Звіт про діяльність центру(ів) соціально-психологічної реабілітації дітей» та Інструкції щодо її заповнення» (зареєстрованого у Міністерстві юстиції України від 0", "g": "ВИКОНАНО", "un": false}, {"id": "13.9", "s": 13, "t": "Формування Звіту про виконання Плану роботи Державної служби України у справах дітей за 2026 рік", "term": "До 20 січня", "u": "Упр. стратегічного розвитку та аналізу процесів", "co": [], "ok": false, "r": 76, "info": "ВИКОНУЄТЬСЯ Сформовано Звіт про виконання Плану роботи Державної служби України у справах дітей за 2026 рік та направлено листом до Міністерства соціальної політики, сім’ї та єдності України Сформовано Звіт про виконання Плану роботи Служби за 9 місяців 2026 року.", "g": "НЕ ВИКОНАНО", "un": false}, {"id": "13.10", "s": 13, "t": "Підготовлено та подано на погодження і затвердження в установленому порядку Пріоритети діяльності і План роботи Державної служби України у справах дітей за 2027 рік", "term": "Листопад-Грудень", "u": "Упр. стратегічного розвитку та аналізу процесів", "co": [], "ok": false, "r": 77, "info": "ВИКОНУЄТЬСЯ План роботи Державної служби України у справах дітей за 2027 рік погоджено з Міністром соціальної політики, сім’ї та єдності України Сформовано доручення Голови щодо підготовки проєкту Плану роботи Служби на 2027 рік", "g": "НЕ ВИКОНАНО", "un": false}, {"id": "14.1", "s": 14, "t": "Забезпечення висвітлення питань діяльності Служби шляхом розробки інформаційно-роз’яснювальних матеріалів для інформування громадськості через офіційний вебпортал Служби, соціальні мережі та засоби масової інформації", "term": "Протягом року", "u": "Упр. стратегічного розвитку та аналізу процесів", "co": [], "ok": true, "r": 79, "info": "ВИКОНАНО Протягом 2026 року Державною службою України у справах дітей забезпечувалося систематичне інформаційне висвітлення діяльності Служби, спрямоване на підвищення рівня обізнаності громадськості щодо реалізації державної політики у сфері захисту прав та законних інтересів дітей, забезпечення їхнього права на зростання в сімейному оточенні, розвитку сімейних форм виховання та підтримки сімей з", "g": "ВИКОНАНО", "un": false}, {"id": "15.1", "s": 15, "t": "Опрацювання проєктів нормативно-правових актів та інших актів законодавства, які надійшли на погодження від інших органів влади", "term": "Протягом року", "u": "Упр. правового забезпечення", "co": [], "ok": true, "r": 81, "info": "ВИКОНАНО Опрацьовано 60 проєктів нормативно-правових актів та інших актів законодавства, які надійшли на погодження від інших органів влади. Внесено до Мінсоцполітики 8 ініціативних змін (у тому числі проєкти НПА) до актів законодавства. Розроблені Службою 3 проєкти НПА прийняті постановами Кабінету Міністрів України: 1) від 8 квітня 2026 р. № 468 \"Про внесення зміни до пункту 6 Порядку використан", "g": "ВИКОНАНО", "un": false}, {"id": "15.2", "s": 15, "t": "Забезпечення представлення інтересів Державної служби України у справах дітей в судах та інших органах. Відстеження судової практики", "term": "Протягом року", "u": "Упр. правового забезпечення", "co": [], "ok": true, "r": 82, "info": "ВИКОНАНО У звітному періоді Управлінням здійснювалось представництво інтересів Служби у 10 судових справах, що розглядаються у рамках цивільного та адміністративного судочинства. Стан позовної роботи формувався під впливом наступних чинників: – активна участь представників Служби у різних заходах та популяризація діяльності Служби; – зростання кількості справ у сфері захисту прав та інтересів діте", "g": "ВИКОНАНО", "un": false}, {"id": "15.3", "s": 15, "t": "Юридичний супровід договірної роботи", "term": "Протягом року", "u": "Упр. правового забезпечення", "co": [], "ok": true, "r": 83, "info": "ВИКОНАНО Порядок ведення договірної роботи в Державній службі України у справах дітей організовано відповідно до наказу від 16.06.2025 № 56-ОС (зі змінами). Юридичною експертизою охоплено 25 договорів та змін до них, які надійшли до Управління правового забезпечення. Управлінням правового забезпечення буде узагальнено інформацію про стан веденням договірної роботи до 01 лютого 2027 року.", "g": "ВИКОНАНО", "un": false}, {"id": "15.4", "s": 15, "t": "Проведення аналізу рішень судів про скасування усиновлення та підготовка інформації щодо підстав і причин прийняття судом таких рішень", "term": "Лютий 2026", "u": "Упр. правового забезпечення", "co": [], "ok": true, "r": 84, "info": "ВИКОНАНО За результатами виконання підпункту 3 пункту 19 Операційного плану заходів на 2024-2026 роки з реалізації Стратегії забезпечення права кожної дитини в Україні на зростання в сімейному оточенні на 2024-2028 роки, затвердженого розпорядженням Кабінету Міністрів України від 26 листопада 2024 р. № 1201-р (далі – Операційний план) проведено аналіз судових рішень про скасування усиновлення та п", "g": "ВИКОНАНО", "un": false}, {"id": "16.1", "s": 16, "t": "Здійснення аудиторських досліджень та аудиторських консультувань за окремо визначеним планом", "term": "Протягом року", "u": "Сектор внутрішнього аудиту", "co": [], "ok": true, "r": 86, "info": "ВИКОНАНО Надано об’єктивні і незалежні висновки, рекомендації, проведено консультації за результатами оцінки діяльності Служби Здійснено проведення внутрішнього аудиту з дослідженням відповідності вимогам законодавства та нормативно-правових актів отримання та використання благодійної допомоги Службою. За результатами проведеного внутрішнього аудиту надано рекомендації щодо усунення виявлених пору", "g": "ВИКОНАНО", "un": false}, {"id": "16.2", "s": 16, "t": "Підготовка звіту про результати діяльності Сектору внутрішнього аудиту за формою 1-ДВА та подання його до Мінфіну", "term": "До 01 лютого", "u": "Сектор внутрішнього аудиту", "co": [], "ok": true, "r": 87, "info": "ВИКОНАНО Направлено до Мінфіну звіт про результати діяльності Сектору внутрішнього аудиту Листом від 23.01.2026 №306/11-21/377/2026 Державна служба України у справах дітей направила Міністерству фінансів України звіт про результати діяльності Сектору внутрішнього аудиту/", "g": "ВИКОНАНО", "un": false}, {"id": "16.3", "s": 16, "t": "Здійснення заходів із удосконалення внутрішнього контролю, спрямованих на забезпечення функціонування елементів внутрішнього контролю в Службі", "term": "Протягом року", "u": "Упр. стратегічного розвитку та аналізу процесів", "co": [], "ok": true, "r": 88, "info": "ВИКОНАНО Організовано роботу щодо удосконалення внутрішнього контролю в Службі Наказом Служби від 22.07.2026 №61-ОС “Про впровадження системи внутрішнього контролю” затверджено оновлений Порядок з організації та функціонування внутрішнього контролю в Державній службі України у справах дітей. Проведено збір пропозицій до переліку ідентифікованих ризиків у діяльності та плану реалізації заходів конт", "g": "ВИКОНАНО", "un": false}, {"id": "17.1", "s": 17, "t": "Переглянути та (за потреби) привести у відповідність до норм чинного законодавства організаційну структуру Служби", "term": "Протягом року", "u": "Відділ управління персоналом", "co": [], "ok": true, "r": 90, "info": "ВИКОНАНО Наказом Служби від 28 травня 2026 року № 46-ОС “Про введення в дію структури та штатного розпису Державної служби України у справах дітей на 2026 рік” з 01 червня 2026 року введено в дію структуру апарату Служби чисельністю 200 штатних одиниць, затверджену Головою Служби та погоджену Міністром соціальної політики, сім’ї та єдності України та штатний розпис Служби на 2026 рік, затверджений", "g": "ВИКОНАНО", "un": false}, {"id": "17.2", "s": 17, "t": "Організувати роботу щодо заповнення вакансій в Службі згідно із вимогами щодо кваліфікації й професійних компетентностей претендентів", "term": "Протягом року", "u": "Відділ управління персоналом", "co": [], "ok": false, "r": 91, "info": "ВИКОНУЄТЬСЯ Станом на 30 вересня 2026 року облікова чисельність працівників Служби складає 74 працівника, з них 73 - державні службовці та 1 - працівник. Відділом управління персоналом підготовлено та направлено 12 жовтня 2026 року Звіт про кількісно-якісний склад персоналу Служби. Станом на 30 вересня 2026 року в Службі 127 вакансій.", "g": "НЕ ВИКОНАНО", "un": false}, {"id": "17.3", "s": 17, "t": "Організувати підвищення рівня професійної компетентності державних службовців Служби та відстежувати й координувати виконання індивідуальних програм професійного розвитку", "term": "Протягом року", "u": "Відділ управління персоналом", "co": [], "ok": false, "r": 92, "info": "ВИКОНУЄТЬСЯ З метою підвищення рівня професійної компетентності державних службовців Служби організовано проходження навчальних курсів (підвищення кваліфікації) та самоосвіти з метою виконання індивідуальних програм професійного розвитку на 2026 рік. Станом на 30 вересня 2026 року державними службовцями Служби виконано та закрито 54 індивідуальні програми професійного розвитку на 2026 рік", "g": "НЕ ВИКОНАНО", "un": false}, {"id": "18.1", "s": 18, "t": "Надання працівникам Служби методичної та консультаційної допомоги з питань дотримання законодавства щодо запобігання корупції", "term": "Протягом року", "u": "Сектор запобігання корупції", "co": [], "ok": true, "r": 94, "info": "ВИКОНАНО. Працівникам Служби надавалися методична та консультаційна допомога з питань дотримання вимог законодавства щодо запобігання корупції. Також кандидатам на посади в Службі надано консультаційну допомогу щодо порядку заповнення та подання декларацій осіб, уповноважених на виконання функцій держави або місцевого самоврядування.", "g": "ВИКОНАНО", "un": false}, {"id": "18.2", "s": 18, "t": "Забезпечення функціонування внутрішніх каналів повідомлення про можливі факти корупційних або пов’язаних з корупцією правопорушень, інших порушень Закону України «Про запобігання корупції» працівниками Служби", "term": "Протягом року", "u": "Сектор запобігання корупції", "co": [], "ok": true, "r": 95, "info": "ВИКОНАНО У Службі забезпечено функціонування внутрішніх каналів повідомлення про можливі факти корупційних або пов’язаних з корупцією правопорушень, інших порушень Закону України «Про запобігання корупції», зокрема шляхом використання спеціалізованої електронної пошти та поштової скриньки для подання відповідних повідомлень працівниками Служби.", "g": "ВИКОНАНО", "un": false}, {"id": "18.3", "s": 18, "t": "Здійснення аналізу виконання Антикорупційної програми Служби", "term": "Липень 2026", "u": "Сектор запобігання корупції", "co": [], "ok": true, "r": 96, "info": "ВИКОНАНО Підготовлено звіт про хід виконання Антикорупційної програми", "g": "ВИКОНАНО", "un": false}, {"id": "19.1", "s": 19, "t": "Підготовка бюджетної декларації, бюджетної пропозиції та бюджетного запиту за бюджетними програмами, розпорядником яких є Служба та подання до Міністерства соціальної політики, сім’ї та єдності України", "term": "Лютий-жовтень", "u": "Упр. фінансового забезпечення та обліку", "co": [], "ok": true, "r": 98, "info": "ВИКОНАНО Сформовано потребу бюджетних коштів для забезпечення діяльності Служби на 2027-2029 роки. Бюджетний запит підготовлено з урахуванням доведеного граничного обсягу бюджетних коштів на 2027-2029 роки та подано до головного розпорядника бюджетних коштів Міністерства соціальної політики, сім’ї та єдності України.", "g": "ВИКОНАНО", "un": false}, {"id": "19.2", "s": 19, "t": "Забезпечення подання бюджетної та фінансової звітності в терміни згідно чинного законодавства", "term": "Протягом року", "u": "Упр. фінансового забезпечення та обліку", "co": [], "ok": true, "r": 99, "info": "ВИКОНАНО Подано бюджетну та фінансову звітність за 2026 рік в терміни згідно чинного законодавства через Систему подачі звітності “Є-звітність” за бюджетними програмами КПКВК 2504010 “Керівництво та управління у сфері усиновлення та захисту прав дітей” та 2501400 “Соціальний захист дітей та сім'ї”.", "g": "ВИКОНАНО", "un": false}, {"id": "20.1", "s": 20, "t": "Організація виконання заходів у сфері технічного захисту інформації", "term": "Протягом року", "u": "Відділ цифрового розвитку та інновацій", "co": [], "ok": true, "r": 101, "info": "ВИКОНАНО Організовано заходи у сфері технічного захисту інформації Успішно проведено первинну авторизацію з безпеки інформаційно-комунікаційної системи (ІКС) «Єдина державна платформа про сімейні форми виховання» відповідно Порядку авторизації з безпеки інформаційних, електронних комунікаційних, інформаційно-комунікаційних, технологічних систем, затвердженого постановою Кабінету Міністрів України ", "g": "ВИКОНАНО", "un": false}, {"id": "20.2", "s": 20, "t": "Підвищення рівня технічного та криптографічного захисту, кібербезпекти, кіберзахисту та безпеки інформаційних технологій в Службі", "term": "Протягом року", "u": "Відділ цифрового розвитку та інновацій", "co": [], "ok": true, "r": 102, "info": "ВИКОНАНО Інтегровано апаратне та програмне забезпечення. Забезпечено підвищення рівня безпеки інформаційно-комунікаційної системи Служби. Проведено сегментацію корпоративної мережі (VLAN) за структурними підрозділами для локалізації загроз. Налаштовано міжмережевий екран з політикою «заборонено за замовчуванням» та географічним блокуванням неавторизованого трафіку. Впроваджено систему регулярного ", "g": "ВИКОНАНО", "un": false}, {"id": "20.3", "s": 20, "t": "Забезпечення доступу працівників Служби до інформаційних систем та реєстрів необхідних для виконання покладених на них завдань", "term": "Протягом року", "u": "Відділ цифрового розвитку та інновацій", "co": [], "ok": true, "r": 103, "info": "ВИКОНАНО Здійснено підключення робочих місць, надання/блокування доступу до інформаційних систем та реєстрів. Забезпечено стабільний та захищений доступ працівників Служби до зовнішніх державних інформаційних систем (зокрема, завдяки розгортанню та супроводу VPN-з'єднань). Оптимізовано процес адміністрування прав доступу (оперативне надання та блокування облікових записів до інформаційних систем і", "g": "ВИКОНАНО", "un": false}, {"id": "20.4", "s": 20, "t": "Забезпечення належної реалізації права дитини на врахування її думки під час вирішення питань, що стосуються її життя", "term": "Протягом року", "u": "Відділ цифрового розвитку та інновацій", "co": [], "ok": false, "r": 104, "info": "ВИКОНУЄТЬСЯ Забезпечено функціонування «гарячої лінії» для дітей для отримання консультацій з питань, що їх турбують, та повідомлення ними про випадки порушення їх прав. У зв'язку з відсутністю бюджетного фінансування на створення та функціонування «гарячої лінії», тривають активні пошуки позабюджетних джерел фінансування. Ведуться переговори з міжнародними партнерами, благодійними фондами та гром", "g": "НЕ ВИКОНАНО", "un": false}];
